import requests, xml.etree.ElementTree as ET
r=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi',params={'db':'pubmed','id':'25079964','retmode':'xml'},timeout=20)
print('HTTP',r.status_code)
root=ET.fromstring(r.text)
for x in root.iter():
 if x.tag in ('ArticleTitle','AbstractText','Journal','Year','Month','Day'):
  t=' '.join(''.join(x.itertext()).split())
  if t: print(x.tag+':',t)
